package dev.zomboid.mts;
import java.util.*;
public final class Inspection {
 public static final int DURATION=30;
 static final Map<Object,Map<Object,Pending>> pending=new WeakHashMap<>();
 static final class Pending {Object player;long started;Pending(Object p,long start){player=p;started=start;}}
 public static boolean finished(long start,long now){return now-start>=DURATION;}
 public static int progress(long start,long now){return (int)Math.max(0,Math.min(100,(now-start)*100/DURATION));}
 static long clock(Object player){return ((Number)R.call(R.call(R.get(player,"entity"),"level"),"getGameTime")).longValue();}
 static void message(Object player,String text){R.call(R.get(player,"entity"),"displayClientMessage",R.call(R.type("net.minecraft.network.chat.Component"),"literal",text),true);}
 static boolean allowed(Object v,Object player){if(!R.yes(R.get(v,"isValid"))||!R.yes(R.call(player,"isValid"))||!R.yes(R.call(R.get(player,"entity"),"isAlive")))return false;Object seat=R.call(player,"getEntityRiding");if(seat!=null&&R.get(seat,"vehicleOn")==v)return true;if(R.yes(R.get(R.get(v,"lockedVar"),"isActive")))return false;Object eye=R.call(player,"getEyePosition"),box=R.get(v,"encompassingBox"),center=R.get(box,"globalCenter");double squared=0;String[] axes={"x","y","z"},radii={"widthRadius","heightRadius","depthRadius"};for(int i=0;i<3;i++){double d=Math.max(0,Math.abs(R.num(R.get(eye,axes[i]))-R.num(R.get(center,axes[i])))-R.num(R.get(box,radii[i])));squared+=d*d;}return squared<=25;}
 public static void start(Object v,Object player){if(R.yes(R.call(R.get(v,"world"),"isClient"))||!allowed(v,player))return;Map<Object,Pending> map=pending.computeIfAbsent(v,k->new HashMap<>());Object id=R.call(player,"getID");if(!map.containsKey(id)){map.put(id,new Pending(player,clock(player)));message(player,"Buscando 0% - Revisando motor");}}
 static void xp(Object v,Object player,long now){try{Object entity=R.get(player,"entity"),skill=R.call(R.type("dev.survivorcreator.skills.Skills"),"get","mechanics");if(skill==null){message(player,"Motor revisado");return;}double before=R.num(R.call(R.type("dev.survivorcreator.skills.Skills"),"xp",entity,skill));R.call(R.type("dev.survivorcreator.skills.Skills"),"addXp",entity,skill,5d);double gained=R.num(R.call(R.type("dev.survivorcreator.skills.Skills"),"xp",entity,skill))-before;if(gained>0)message(player,String.format("Mecanica +%.1f XP",gained));else message(player,"Motor revisado");}catch(IllegalStateException missing){Throwable root=missing;while(root.getCause()!=null)root=root.getCause();if(!(root instanceof ClassNotFoundException))throw missing;}}
 public static void tick(Object v){if(!RoadDriving.transport(v)||R.yes(R.call(R.get(v,"world"),"isClient")))return;Object request=R.call(v,"getOrCreateVariable","pz_inspect_request");if(R.yes(R.get(request,"isActive"))){R.call(request,"setTo",0d,false);Object controller=R.call(v,"getController");if(controller!=null&&R.type("minecrafttransportsimulator.mcinterface.IWrapperPlayer").isInstance(controller))start(v,controller);}Map<Object,Pending> map=pending.get(v);if(map==null)return;Iterator<Pending> it=map.values().iterator();while(it.hasNext()){Pending p=it.next();if(!allowed(v,p.player)){it.remove();message(p.player,"Revision cancelada");continue;}long now=clock(p.player);if(finished(p.started,now)){it.remove();xp(v,p.player,now);R.call(p.player,"sendPacket",R.make("minecrafttransportsimulator.packets.instances.PacketEntityGUIRequest",v,p.player,R.get(R.type("minecrafttransportsimulator.packets.instances.PacketEntityGUIRequest$EntityGUIType"),"INSTRUMENTS")));}else message(p.player,"Buscando "+progress(p.started,now)+"% - Revisando motor");}if(map.isEmpty())pending.remove(v);}
}
